export interface CourseSelectionRequest {
  courseId?: string;
  hole?: number;
}

export interface CourseSelection {
  course: Course;
  hole: Hole;
  /** Zero-based index inside `course.holes`. */
  holeIndex: number;
  /** One-based hole number shown in HUD and URLs. */
  holeNumber: number;
  /** False when the request fell back to the default course. */
  matchedCourse: boolean;
  /** False when the requested hole was missing or out of range. */
  matchedHole: boolean;
}

/** Resolves a menu or URL request into a concrete course and starting hole. */
export function resolveCourseSelection(
  request: CourseSelectionRequest = {},
  random: CourseRandom = Math.random,
): CourseSelection {
  const requested = request.courseId?.trim();
  const isRandom = requested === RANDOM_COURSE_ID;
  const course = isRandom ? pickRandomCourse(random) : getCourse(requested) ?? requireCourse(DEFAULT_COURSE_ID);
  const requestedHole = request.hole;
  const matchedHole =
    requestedHole !== undefined &&
    Number.isInteger(requestedHole) &&
    requestedHole >= 1 &&
    requestedHole <= course.holes.length;
  const holeIndex = matchedHole ? requestedHole - 1 : 0;
  return {
    course,
    hole: course.holes[holeIndex]!,
    holeIndex,
    holeNumber: holeIndex + 1,
    matchedCourse: isRandom || (requested !== undefined && course.id === requested),
    matchedHole,
